SELECT order_id, CASE WHEN quantity >= 7 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, PERCENTILE_APPROX(unit_price, 0.9) AS unit_price_p90, APPROX_PERCENTILE(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, APPROX_PERCENTILE(quantity, 0.9) AS quantity_p90 FROM order_items GROUP BY CUBE (order_id, CASE WHEN quantity >= 7 THEN 'HIGH' ELSE 'LOW' END) ORDER BY quantity_p90;
